   346	/// The parts a command runs as: itself, or — a `jobs retry` of an
   347	/// `--ignore-existing` job whose failed writes left this run's own
   348	/// incomplete copies (review cr-jl4-1) — those paths with the flag off,
   349	/// then the rest with it, as the in-command retry passes split them.
   350	fn retry_parts(args: &TransferArgs) -> Vec<TransferArgs> {
   351	    use std::collections::HashSet;
   352	    let (Some(left), Some(all)) = (&args.retry_left_in_place, &args.retry_only) else {
   353	        return vec![args.clone()];
   354	    };
   355	    let empty = HashSet::new();
   356	    let left_raw = args.retry_left_in_place_raw.as_ref().unwrap_or(&empty);
   357	    let all_raw = args.retry_only_raw.as_ref().unwrap_or(&empty);
   358	    if !args.ignore_existing || (left.is_empty() && left_raw.is_empty()) {
   359	        return vec![args.clone()];
   360	    }
   361	    let mut own = args.clone();
   362	    own.retry_only = Some(left.clone());
   363	    own.retry_only_raw = Some(left_raw.clone());
   364	    own.ignore_existing = false;
   365	    own.retry_left_in_place = None;
   366	    own.retry_left_in_place_raw = None;
   367	    let rest: HashSet<std::path::PathBuf> = all.difference(left).cloned().collect();
   368	    let rest_raw: HashSet<Vec<u8>> = all_raw.difference(left_raw).cloned().collect();
   369	    if rest.is_empty() && rest_raw.is_empty() {
   370	        return vec![own];
   371	    }
   372	    let mut others = args.clone();
   373	    others.retry_only = Some(rest);
   374	    others.retry_only_raw = Some(rest_raw);
   375	    others.retry_left_in_place = None;
   376	    others.retry_left_in_place_raw = None;
   377	    vec![own, others]
   378	}
